package com.example.gradleproject;

import android.os.Bundle;
import android.support.v7.app.AppCompatActivity;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;
import android.widget.TextView;

import com.example.gradleproject.model.User;
import com.example.gradleproject.service.UserService;

import java.util.List;

public class MainActivity extends AppCompatActivity {

    private EditText name;
    private EditText email;
    private Button add;
    private TextView result;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        name = (EditText) findViewById(R.id.name);
        email = (EditText) findViewById(R.id.email);
        add = (Button) findViewById(R.id.add);
        result = (TextView) findViewById(R.id.result);

        add.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                UserService userService = new UserService();
                User user = new User(name.getText().toString(), email.getText().toString());
                userService.addUser(user);
                List&lt;User&gt; users = userService.getUsers();
                String text = "";
                for (User u : users) {
                    text += u.getName() + " " + u.getEmail() + "\n";
                }
                result.setText(text);
            }
        });
    }
}
