     * @param data the data to encrypt
     * @return the encrypted data
     */
    byte[] encrypt(byte[] data);

    /**
     * Decrypts the given data.
     *
     * @param data the data to decrypt
     * @return the decrypted data
     */
    byte[] decrypt(byte[] data);

    /**
     * Encrypts the given input stream and writes the result to the output stream.
     *
     * @param in the input stream to read from
     * @param out the output stream to write to
     * @throws IOException if an I/O error occurs
     */
    void encrypt(InputStream in, OutputStream out) throws IOException;

    /**
     * Decrypts the given input stream and writes the result to the output stream.
     *
     * @param in the input stream to read from
     * @param out the output stream to write to
     * @throws IOException if an I/O error occurs
     */
    void decrypt(InputStream in, OutputStream out) throws IOException;
}
